"use client";

import { useState } from "react";
import { Trash2, Edit3, FileText, Plus, Calendar } from "lucide-react";
import { Button } from "@/components/ui/button";
import TaskFormModal from "./TaskFormModal";
import { deleteTask } from "@/app/actions/task-actions";

export default function TaskListClient({ initialTasks }: { initialTasks: any[] }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<any>(null);

  const handleEdit = (task: any) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleNew = () => {
    setEditingTask(null);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center bg-[#111a45]/40 p-6 rounded-[2rem] border border-teal-400/10 backdrop-blur-md">
        <div>
          <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-teal-300 to-fuchsia-400 uppercase tracking-tighter">
            Documenten
          </h1>
          <p className="text-teal-400/50 text-xs mt-1 font-medium tracking-widest uppercase">Beheer je scrum processen</p>
        </div>
        <Button 
          onClick={handleNew}
          className="bg-gradient-to-r from-teal-400 to-fuchsia-400 text-[#070B24] font-black px-8 py-7 rounded-2xl hover:scale-105 transition-all shadow-[0_0_30px_rgba(45,212,191,0.3)] active:scale-95"
        >
          <Plus className="mr-2 h-6 w-6" /> NIEUWE TAAK
        </Button>
      </div>

      <div className="grid gap-4">
        {initialTasks.map((task) => (
          <div key={task.id} className="group bg-[#0E153A]/50 border border-teal-400/20 p-6 rounded-[2rem] flex items-center justify-between hover:border-teal-400/50 transition-all backdrop-blur-xl">
            <div className="flex items-center gap-5">
              <div className="p-4 bg-gradient-to-br from-teal-400/20 to-fuchsia-500/20 rounded-2xl text-teal-300 border border-teal-400/20 shadow-inner">
                <FileText size={28} />
              </div>
              <div>
                <h3 className="text-teal-50 font-bold text-xl group-hover:text-teal-300 transition-colors">{task.title}</h3>
                <div className="flex gap-3 mt-2 items-center">
                  <span className="text-[10px] text-fuchsia-400 font-black uppercase tracking-[0.2em] bg-fuchsia-500/10 px-3 py-1 rounded-full border border-fuchsia-500/20">
                    Sprint {task.sprint || "1"}
                  </span>
                  <span className="text-[10px] text-teal-400/40 flex items-center gap-1 font-bold">
                    <Calendar size={12} className="opacity-50" /> {new Date(task.createdAt).toLocaleDateString('nl-NL')}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <Button onClick={() => handleEdit(task)} variant="ghost" className="h-12 w-12 text-teal-400 hover:bg-teal-400/10 hover:text-teal-200 rounded-xl transition-all">
                <Edit3 size={20} />
              </Button>
              <Button 
                onClick={async () => { if(confirm("Weet je zeker dat je dit document wilt verwijderen?")) await deleteTask(task.id); }} 
                variant="ghost" 
                className="h-12 w-12 text-red-400/60 hover:bg-red-500/10 hover:text-red-400 rounded-xl transition-all"
              >
                <Trash2 size={20} />
              </Button>
            </div>
          </div>
        ))}
      </div>

      <TaskFormModal 
        open={isModalOpen} 
        setOpen={setIsModalOpen} 
        initialData={editingTask} 
      />
    </div>
  );
}