"use client";

import { useState, useEffect } from "react";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogDescription, // Artık hata vermez
  DialogFooter        // Artık hata vermez
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { createNewTask, updateTask } from "@/app/actions/task-actions";

export default function TaskFormModal({ 
  isOpen, 
  onClose, 
  editingTask 
}: { 
  isOpen: boolean; 
  onClose: () => void; 
  editingTask?: any 
}) {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (editingTask) {
      setTitle(editingTask.title || "");
      setContent(editingTask.content || "");
    } else {
      setTitle("");
      setContent("");
    }
  }, [editingTask, isOpen]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    setLoading(true);

    try {
      let result;
      if (editingTask) {
        result = await updateTask(editingTask.id, { title, content });
      } else {
        result = await createNewTask(title, content);
      }
      if (result.success) onClose();
      else alert("Fout bij opslaan.");
    } catch (error) {
      alert("Er is bir hata oluştu.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      {/* aria-describedby={undefined} ekleyerek konsol hatasını susturuyoruz */}
      <DialogContent className="max-w-2xl bg-white" aria-describedby={undefined}>
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle className="text-xl font-bold">
              {editingTask ? "Taak Bewerken" : "Nieuwe Taak Toevoegen"}
            </DialogTitle>
          </DialogHeader>

          <div className="grid gap-6 py-6">
            <div className="grid gap-2">
              <Label htmlFor="title" className="font-semibold">Titel</Label>
              <Input
                id="title"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="content" className="font-semibold">Inhoud</Label>
              <Textarea
                id="content"
                value={content}
                onChange={(e) => setContent(e.target.value)}
                className="h-[200px] resize-none"
              />
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>Annuleren</Button>
            <Button type="submit" disabled={loading || !title} className="bg-blue-600 text-white">
              {loading ? "Verwerken..." : "Opslaan"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}